package com.corecs.solid.rules;import com.corecs.solid.model.*;import java.util.*;public class IspRule implements SolidRule{public List<Issue> analyze(List<ClassInfo> cs){List<Issue> o=new ArrayList<>();for(var c:cs)if(c.interfaceType()&&c.methods().size()>4)o.add(new Issue("ISP","Potential",c.name(),"Interface may be too broad","An interface with many operations can force implementers to depend on methods they do not need.","Split the contract into smaller role-focused interfaces where clients use different subsets."));return o;}}
